      q('UPDATE channels SET is_archived=0 WHERE id=?',(cid,)); return self.send(201,{'message':None,'channel':channel(q('SELECT * FROM channels WHERE id=?',(cid,),True))})
     elif body.split()[0] not in ('/me','/shrug'):return self.send(400,{})"""
